"""Supplied deterministic message scheduler; you do not edit this file.

Nodes never call other nodes directly. Every gossip/ACK goes through send(),
which may delay or drop it. This is a simulation, not actual OS networking.
"""
from __future__ import annotations

import heapq
import random
from collections import Counter
from collections.abc import Callable

from node import GossipNode


def make_topology(names: list[str], shape: str = "ring") -> dict[str, list[str]]:
    peers = {name: set() for name in names}
    if shape == "ring":
        for index, node in enumerate(names):
            other = names[(index + 1) % len(names)]
            if other != node:
                peers[node].add(other)
                peers[other].add(node)
    elif shape == "mesh":
        for node in names:
            peers[node].update(set(names) - {node})
    else:
        raise ValueError(f"Unknown topology: {shape}")
    return {name: sorted(group) for name, group in peers.items()}


class Network:
    def __init__(self, names: list[str], *, shape: str = "ring",
                 loss_rate: float = 0.0, seed: int = 42,
                 latency: float = 0.1, step: float = 0.1,
                 initially_online: set[str] | None = None,
                 node_class: type[GossipNode] = GossipNode):
        if not names or len(set(names)) != len(names):
            raise ValueError("Node IDs must be unique and nonempty")
        if not 0 <= loss_rate <= 1:
            raise ValueError("Loss rate must be between 0 and 1")
        self.names = list(names)
        self.shape = shape
        self.topology = make_topology(names, shape)
        self.loss_rate = loss_rate
        self.random = random.Random(seed)
        self.seed = seed
        self.latency = latency
        self.step = step
        self.node_class = node_class
        self.now = 0.0
        self.online = set(names) if initially_online is None else set(initially_online)
        self.blocked: set[frozenset[str]] = set()
        self.nodes = {name: self._create_node(name) for name in names}
        self.queue: list[tuple[float, int, str, object]] = []
        self.serial = 0
        self.metrics: Counter = Counter()
        self.events: set[int] = set()
        self.injections: list[dict] = []
        self.trace: list[dict] = []
        self.snapshots: list[dict] = []
        self.first_seen: dict[str, dict[int, float]] = {name: {} for name in names}
        self.ready_after = 0.0
        self.converged_at: float | None = None
        self._refresh_neighbors()

    def _create_node(self, name: str) -> GossipNode:
        return self.node_class(name, lambda dest, kind, body, src=name:
                               self.send(src, dest, kind, body))

    def _push(self, at: float, kind: str, data: object) -> None:
        self.serial += 1
        heapq.heappush(self.queue, (round(at, 5), self.serial, kind, data))

    def schedule(self, at: float, label: str, action: Callable[[], None]) -> None:
        self._push(at, "action", (label, action))

    def _log(self, event_type: str, **fields) -> None:
        self.trace.append({"at": round(self.now, 2), "type": event_type, **fields})

    def _refresh_neighbors(self) -> None:
        for name, node in self.nodes.items():
            effective = [p for p in self.topology[name] if p in self.online] if name in self.online else []
            node.update_neighbors(effective)

    def inject(self, origin: str, event_id: int) -> None:
        if origin not in self.online:
            raise ValueError(f"Cannot inject at offline node {origin}")
        self.events.add(event_id)
        self.injections.append({"at": round(self.now, 2), "node": origin, "event": event_id})
        self.ready_after = max(self.ready_after, self.now)
        self.converged_at = None
        reply = self.nodes[origin].broadcast(event_id)
        if reply.get("type") != "broadcast_ok":
            raise AssertionError("A local broadcast must acknowledge acceptance")
        self._log("inject", node=origin, ids=[event_id])

    def send(self, src: str, dest: str, kind: str, body: dict) -> None:
        self.metrics["messages_attempted"] += 1
        self.metrics[f"{kind}_attempted"] += 1
        fields = {"src": src, "dest": dest, "kind": kind, "ids": list(body["ids"])}
        edge = frozenset([src, dest])
        failure = (src not in self.online or dest not in self.online or edge in self.blocked)
        if not failure and self.loss_rate and self.random.random() < self.loss_rate:
            failure = True
        if failure:
            self.metrics["messages_dropped"] += 1
            self._log("drop", **fields)
        else:
            self._push(self.now + self.latency, "deliver", (src, dest, kind, dict(body)))
            self._log("send", **fields)

    def _deliver(self, src: str, dest: str, kind: str, body: dict) -> None:
        fields = {"src": src, "dest": dest, "kind": kind, "ids": list(body["ids"])}
        if src not in self.online or dest not in self.online or frozenset([src, dest]) in self.blocked:
            self.metrics["messages_dropped"] += 1
            self._log("drop", **fields)
            return
        self.metrics["messages_delivered"] += 1
        self._log("deliver", **fields)
        if kind == "gossip":
            self.nodes[dest].receive_gossip(src, body["ids"])
        elif kind == "ack":
            self.nodes[dest].receive_ack(src, body["ids"])
        else:
            raise ValueError(f"Unknown network message kind: {kind}")

    def partition(self, group_a: set[str], enabled: bool) -> None:
        group_b = set(self.names) - group_a
        pairs = {frozenset([a, b]) for a in group_a for b in group_b}
        if enabled:
            self.blocked.update(pairs)
            self._log("partition", group_a=sorted(group_a), group_b=sorted(group_b))
        else:
            self.blocked.difference_update(pairs)
            self.ready_after = max(self.ready_after, self.now)
            self.converged_at = None
            self._log("heal", group_a=sorted(group_a), group_b=sorted(group_b))

    def set_online(self, node_id: str, online: bool, *, reset: bool = False) -> None:
        if node_id not in self.nodes:
            raise KeyError(node_id)
        if reset:
            self.nodes[node_id] = self._create_node(node_id)
            self.first_seen[node_id] = {}
        if online:
            self.online.add(node_id)
        else:
            self.online.discard(node_id)
        self._refresh_neighbors()
        self.ready_after = max(self.ready_after, self.now)
        self.converged_at = None
        self._log("restart" if reset else ("online" if online else "offline"), node=node_id)

    def _work_due(self) -> None:
        while self.queue and self.queue[0][0] <= self.now + 1e-8:
            _, _, kind, data = heapq.heappop(self.queue)
            if kind == "action":
                label, action = data
                action()
            else:
                self._deliver(*data)

    def _snapshot(self) -> None:
        nodes = {}
        for name, node in self.nodes.items():
            state = node.snapshot()
            state["online"] = name in self.online
            nodes[name] = state
            if name in self.online:
                for event in node.known:
                    self.first_seen[name].setdefault(event, self.now)
        self.snapshots.append({"at": round(self.now, 2), "nodes": nodes,
                               "blocked": [sorted(edge) for edge in sorted(self.blocked, key=lambda v: sorted(v))]})

    def _all_converged(self) -> bool:
        return bool(self.events) and all(self.nodes[n].known == self.events for n in self.online)

    def run(self, duration: float = 12.0) -> dict:
        for index in range(int(round(duration / self.step)) + 1):
            self.now = round(index * self.step, 5)
            self._work_due()
            for name in self.names:
                if name in self.online:
                    self.nodes[name].tick(self.now)
            self._work_due()
            self._snapshot()
            if (self.now + 1e-8 >= self.ready_after and self._all_converged()
                    and self.converged_at is None):
                self.converged_at = self.now

        total_retries = sum(n.counters["retry_batches"] for n in self.nodes.values())
        duplicate_count = sum(n.counters["duplicates"] for n in self.nodes.values())
        last_injection = max(item["at"] for item in self.injections) if self.injections else 0.0
        return {
            "nodes": self.names, "topology": self.topology,
            "expected": sorted(self.events), "injections": self.injections,
            "trace": self.trace, "timeline": self.snapshots,
            "final": {name: self.nodes[name].read() for name in self.names},
            "online": sorted(self.online),
            "metrics": {
                "converged": self._all_converged(),
                "converged_at": self.converged_at,
                "ready_after": round(self.ready_after, 3),
                "last_injection_at": last_injection,
                "convergence_seconds": (round(self.converged_at - last_injection, 3)
                                        if self.converged_at is not None else None),
                "recovery_seconds": (round(self.converged_at - self.ready_after, 3)
                                        if self.converged_at is not None else None),
                "messages_attempted": self.metrics["messages_attempted"],
                "messages_delivered": self.metrics["messages_delivered"],
                "messages_dropped": self.metrics["messages_dropped"],
                "gossip_attempted": self.metrics["gossip_attempted"],
                "ack_attempted": self.metrics["ack_attempted"],
                "retry_batches": total_retries,
                "duplicates_suppressed": duplicate_count,
            },
            "settings": {"topology": self.shape, "loss_rate": self.loss_rate,
                         "seed": self.seed, "latency": self.latency,
                         "duration": duration, "step": self.step},
        }
